// pick.cpp — screen-space nearest-point picking (C++17)
//
// Given a crosshair position and a list of projected points, returns the index
// of the best candidate inside a pick radius, skipping points behind the camera.
//
// Scoring: each candidate's pixel distance to the crosshair is divided by its
// weight, so higher-weight points "win" at slightly larger distances. The radius
// test uses the raw (unweighted) distance, so weights never extend the pick area.

#include <cmath>
#include <cstddef>
#include <limits>
#include <optional>
#include <vector>

namespace pick {

struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;
};

struct ScreenPoint {
    Vec2  pos;            // screen-space position in pixels
    float w      = 1.0f;  // clip-space w (or view-space depth); <= 0 means behind camera
    float weight = 1.0f;  // priority; > 0. Larger = preferred
};

struct PickResult {
    std::size_t index;     // index into the input vector
    float       distance;  // raw pixel distance to the crosshair
    float       score;     // distance / weight (lower is better)
};

// Points with w at or below this are treated as behind / on the near plane.
inline constexpr float kNearEpsilon = 1e-6f;

std::optional<PickResult> pickNearest(const Vec2& crosshair,
                                      const std::vector<ScreenPoint>& points,
                                      float radius)
{
    if (!(radius > 0.0f) || points.empty())
        return std::nullopt;

    const float radiusSq = radius * radius;

    std::optional<PickResult> best;
    float bestScore = std::numeric_limits<float>::infinity();

    for (std::size_t i = 0; i < points.size(); ++i) {
        const ScreenPoint& p = points[i];

        // Behind the camera: projected position is meaningless (mirrored).
        if (!(p.w > kNearEpsilon))
            continue;

        // Ignore invalid weights and non-finite projections.
        if (!(p.weight > 0.0f) || !std::isfinite(p.pos.x) || !std::isfinite(p.pos.y))
            continue;

        const float dx = p.pos.x - crosshair.x;
        const float dy = p.pos.y - crosshair.y;
        const float distSq = dx * dx + dy * dy;

        if (distSq > radiusSq)
            continue;

        const float dist  = std::sqrt(distSq);
        const float score = dist / p.weight;

        // Tie-break on raw distance so equal scores prefer the closer point.
        if (score < bestScore || (score == bestScore && best && dist < best->distance)) {
            bestScore = score;
            best = PickResult{i, dist, score};
        }
    }

    return best;
}

} // namespace pick

#ifdef PICK_DEMO
#include <cstdio>

int main()
{
    using namespace pick;

    const Vec2 crosshair{640.0f, 360.0f};
    const std::vector<ScreenPoint> pts = {
        {{650.0f, 365.0f}, 1.0f, 1.0f},   // close, normal weight
        {{660.0f, 370.0f}, 1.0f, 3.0f},   // a bit farther, high weight -> wins
        {{641.0f, 360.0f}, -2.0f, 1.0f},  // behind camera -> skipped
        {{900.0f, 100.0f}, 1.0f, 10.0f},  // outside radius -> skipped
    };

    if (auto r = pickNearest(crosshair, pts, 50.0f))
        std::printf("picked %zu  dist=%.2f  score=%.2f\n", r->index, r->distance, r->score);
    else
        std::printf("nothing picked\n");
}
#endif
